diff --git a/usercase-test-coderl/metastore_stateful_test.go b/usercase-test-coderl/metastore_stateful_test.go
new file mode 100644
--- /dev/null
+++ b/usercase-test-coderl/metastore_stateful_test.go
@@ -0,0 +1,554 @@
+package usercase_test_coderl
+
+import (
+	"context"
+	"encoding/binary"
+	"fmt"
+	"io"
+	"net"
+	"os"
+	"os/user"
+	"runtime"
+	"strings"
+	"testing"
+	"time"
+
+	"github.com/apache/thrift/lib/go/thrift"
+	root "github.com/beltran/gohive"
+	rootmeta "github.com/beltran/gohive/hive_metastore"
+	v2 "github.com/beltran/gohive/v2"
+	v2meta "github.com/beltran/gohive/v2/hive_metastore"
+)
+
+
+
+
+
+
+type rootMetastoreHandler struct {
+	rootmeta.ThriftHiveMetastore
+	databases []string
+}
+
+func (h rootMetastoreHandler) GetAllDatabases(ctx context.Context) ([]string, error) {
+	return h.databases, nil
+}
+
+type v2MetastoreHandler struct {
+	v2meta.ThriftHiveMetastore
+	databases []string
+}
+
+func (h v2MetastoreHandler) GetAllDatabases(ctx context.Context) ([]string, error) {
+	return h.databases, nil
+}
+
+func startRootMetastore(t *testing.T, databases []string) (string, int, <-chan struct{}) {
+	t.Helper()
+	ln, err := net.Listen("tcp", "127.0.0.1:0")
+	if err != nil {
+		t.Fatalf("listen root metastore: %v", err)
+	}
+	done := make(chan struct{})
+	go func() {
+		defer close(done)
+		defer ln.Close()
+		conn, err := ln.Accept()
+		if err != nil {
+			return
+		}
+		defer conn.Close()
+		socket := thrift.NewTSocketFromConnTimeout(conn, time.Second)
+		transport, err := thrift.NewTBufferedTransportFactory(4096).GetTransport(socket)
+		if err != nil {
+			return
+		}
+		defer transport.Close()
+		protocol := thrift.NewTBinaryProtocolFactoryDefault().GetProtocol(transport)
+		processor := rootmeta.NewThriftHiveMetastoreProcessor(rootMetastoreHandler{databases: databases})
+		for {
+			ok, err := processor.Process(context.Background(), protocol, protocol)
+			if err != nil || !ok {
+				return
+			}
+		}
+	}()
+	addr := ln.Addr().(*net.TCPAddr)
+	return "127.0.0.1", addr.Port, done
+}
+
+func startV2Metastore(t *testing.T, databases []string) (string, int, <-chan struct{}) {
+	t.Helper()
+	ln, err := net.Listen("tcp", "127.0.0.1:0")
+	if err != nil {
+		t.Fatalf("listen v2 metastore: %v", err)
+	}
+	done := make(chan struct{})
+	go func() {
+		defer close(done)
+		defer ln.Close()
+		conn, err := ln.Accept()
+		if err != nil {
+			return
+		}
+		defer conn.Close()
+		socket := thrift.NewTSocketFromConnTimeout(conn, time.Second)
+		transport, err := thrift.NewTBufferedTransportFactory(4096).GetTransport(socket)
+		if err != nil {
+			return
+		}
+		defer transport.Close()
+		protocol := thrift.NewTBinaryProtocolFactoryDefault().GetProtocol(transport)
+		processor := v2meta.NewThriftHiveMetastoreProcessor(v2MetastoreHandler{databases: databases})
+		for {
+			ok, err := processor.Process(context.Background(), protocol, protocol)
+			if err != nil || !ok {
+				return
+			}
+		}
+	}()
+	addr := ln.Addr().(*net.TCPAddr)
+	return "127.0.0.1", addr.Port, done
+}
+
+func waitForServerDone(t *testing.T, done <-chan struct{}) {
+	t.Helper()
+	select {
+	case <-done:
+	case <-time.After(time.Second):
+		t.Fatalf("metastore server connection did not close within 1s")
+	}
+}
+
+func startClosingListener(t *testing.T) (string, int) {
+	t.Helper()
+	ln, err := net.Listen("tcp", "127.0.0.1:0")
+	if err != nil {
+		t.Fatalf("listen closing socket: %v", err)
+	}
+	go func() {
+		conn, err := ln.Accept()
+		if err == nil {
+			time.Sleep(30 * time.Millisecond)
+			conn.Close()
+		}
+		ln.Close()
+	}()
+	addr := ln.Addr().(*net.TCPAddr)
+	return "127.0.0.1", addr.Port
+}
+
+type saslProbeMessage struct {
+	status byte
+	body   []byte
+}
+
+func readSaslProbeMessage(r io.Reader) (saslProbeMessage, error) {
+	header := make([]byte, 5)
+	if _, err := io.ReadFull(r, header); err != nil {
+		return saslProbeMessage{}, err
+	}
+	length := binary.BigEndian.Uint32(header[1:])
+	body := make([]byte, length)
+	if length > 0 {
+		if _, err := io.ReadFull(r, body); err != nil {
+			return saslProbeMessage{}, err
+		}
+	}
+	return saslProbeMessage{status: header[0], body: body}, nil
+}
+
+func startSaslProbe(t *testing.T) (string, int, <-chan []saslProbeMessage) {
+	t.Helper()
+	ln, err := net.Listen("tcp", "127.0.0.1:0")
+	if err != nil {
+		t.Fatalf("listen sasl probe: %v", err)
+	}
+	messages := make(chan []saslProbeMessage, 1)
+	go func() {
+		defer ln.Close()
+		var got []saslProbeMessage
+		defer func() {
+			messages <- got
+			close(messages)
+		}()
+		conn, err := ln.Accept()
+		if err != nil {
+			return
+		}
+		defer conn.Close()
+		_ = conn.SetDeadline(time.Now().Add(time.Second))
+		for i := 0; i < 2; i++ {
+			msg, err := readSaslProbeMessage(conn)
+			if err != nil {
+				return
+			}
+			got = append(got, msg)
+		}
+	}()
+	addr := ln.Addr().(*net.TCPAddr)
+	return "127.0.0.1", addr.Port, messages
+}
+
+func panicValue(fn func()) (value any) {
+	defer func() {
+		value = recover()
+	}()
+	fn()
+	return nil
+}
+
+f

